(131573, 'itIT', 'L''Orda ha perso il controllo dell''Osservatorio.', '', 25549),
(131572, 'itIT', 'L''Orda ha preso il controllo dell''Osservatorio.', '', 25549),
(131571, 'itIT', 'L''Alleanza ha perso il controllo dell''Osservatorio.', '', 25549),
(131570, 'itIT', 'L''Alleanza ha preso il controllo dell''Osservatorio.', '', 25549),
(131569, 'itIT', 'Uccidi il responsabile di tutto questo!', '', 25549),
(131568, 'itIT', 'Grazie per avermi salvato.', '', 25549),
(131567, 'itIT', 'Grazie.', '', 25549),
(131565, 'itIT', 'Clookle sottoterra!', '', 25549),
(131566, 'itIT', 'Uccidi Giadafulgida!', '', 25549),
(131564, 'itIT', 'Salva Clookle!', '', 25549),
(131563, 'itIT', 'Trova Clookle!', '', 25549),
(131561, 'itIT', 'Aiuta Clookle!', '', 25549),
(131559, 'itIT', 'Giadafulgida hanno antidoto!', '', 25549),
(131557, 'itIT', 'Sei $gil migliore:la migliore;!', '', 25549),
(131556, 'itIT', 'Sei $gfantastico:fantastica;.', '', 25549),
(131555, 'itIT', 'Urrà!', '', 25549),
(131554, 'itIT', 'Sì!', '', 25549),
(131553, 'itIT', 'Grazie!', '', 25549),
(131552, 'itIT', 'Ti voglio bene.', '', 25549),
(131551, 'itIT', '<Il Cucciolo di Lunagufo sembra essere molto felice al tuo fianco.>', '', 25549),
(131550, 'itIT', 'Somministra l''antidoto.', 'Somministra l''antidoto.', 25549),
(131549, 'itIT', '...', '', 25549),
(131548, 'itIT', 'Aiutami.', '', 25549),
(131547, 'itIT', 'Per favore, aiutami.', '', 25549),
(131546, 'itIT', 'Aiuto...', '', 25549),
(131545, 'itIT', 'Ugh...', '', 25549),
(131538, 'itIT', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t %s inizia a lanciare |cFFFF0000|Hspell:244509|h[Sorellanza dei Sargerei]|h|r.', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t %s inizia a lanciare |cFFFF0000|Hspell:244509|h[Sorellanza dei Sargerei]|h|r.', 25549),
