INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(116758, 'itIT', 'Abbiamo... fallito.', '', 25549),
(116757, 'itIT', 'Inconcepibile...', '', 25549),
(116756, 'itIT', 'Non posso perdere contro un miserabile come te!', '', 25549),
(116754, 'itIT', 'Non possiamo fermarli!', '', 25549),
(116753, 'itIT', 'Elisande, ti ho deluso...', '', 25549),
(116747, 'itIT', 'Percepisci una grande fonte di Energia di Faglia vicino a te.', 'Percepisci una grande fonte di Energia di Faglia vicino a te.', 25549),
(116746, 'itIT', 'Ci sono così tanti amici con cui giocare!', 'Ci sono così tanti amici con cui giocare!', 25549),
(116745, 'itIT', 'Ti senti a casa.', 'Ti senti a casa.', 25549),
(116744, 'itIT', 'Questi cristalli sono ENORMI!', 'Questi cristalli sono ENORMI!', 25549),
(116743, 'itIT', 'Avverti delle strutture torreggianti sopra di te.', 'Avverti delle strutture torreggianti sopra di te.', 25549),
(116742, 'itIT', 'Percepisci uno squarcio nel tessuto della magia vicino a te.', 'Percepisci uno squarcio nel tessuto della magia vicino a te.', 25549),
(116741, 'itIT', 'Avverti l''Energia di Faglia tutto intorno a te.', 'Avverti l''Energia di Faglia tutto intorno a te.', 25549),
(116740, 'itIT', 'Ci sono dei cristalli bellissimi qui!', 'Ci sono dei cristalli bellissimi qui!', 25549),
(116738, 'itIT', 'Senti il rumore di una cascata nelle vicinanze.', 'Senti il rumore di una cascata nelle vicinanze.', 25549),
(116739, 'itIT', 'Provi ribrezzo e pietà per quelle creature.', 'Provi ribrezzo e pietà per quelle creature.', 25549),
(116737, 'itIT', 'Percepisci l''immagine della luna.', 'Percepisci l''immagine della luna.', 25549),
(116736, 'itIT', 'Ti senti come se fossi tra amici.', 'Ti senti come se fossi tra amici.', 25549),
(116735, 'itIT', 'Senti il crepitio di un fuoco.', 'Senti il crepitio di un fuoco.', 25549),
(116734, 'itIT', 'Percepisci la terra tremare vicino a te.', 'Percepisci la terra tremare vicino a te.', 25549),
(116733, 'itIT', 'Senti l''odore di terra umida e scura.', 'Senti l''odore di terra umida e scura.', 25549),
(116732, 'itIT', 'Avverti un''oscurità incombente.', 'Avverti un''oscurità incombente.', 25549),
(116731, 'itIT', 'Ti chiedi se i fantasmi possano davvero essere amichevoli.', 'Ti chiedi se i fantasmi possano davvero essere amichevoli.', 25549),
(116730, 'itIT', 'Percepisci le immagini di graziose creature galoppanti.', 'Percepisci le immagini di graziose creature galoppanti.', 25549),
(116729, 'itIT', 'Avverti un senso di sicurezza proveniente dall''alto.', 'Avverti un senso di sicurezza proveniente dall''alto.', 25549),
(116728, 'itIT', 'Senti il debole scorrere dell''acqua.', 'Senti il debole scorrere dell''acqua.', 25549),
(116727, 'itIT', 'Senti ali sbattere, zoccoli calpestare e artigli scavare.', 'Senti ali sbattere, zoccoli calpestare e artigli scavare.', 25549),
(116726, 'itIT', 'Percepisci la delicata fragranza dei boccioli sotto il sole.', 'Percepisci la delicata fragranza dei boccioli sotto il sole.', 25549),
(116725, 'itIT', 'Senti le foglie frusciare nel vento.', 'Senti le foglie frusciare nel vento.', 25549),
(116724, 'itIT', 'Avverti la presenza di un essere superiore.', 'Avverti la presenza di un essere superiore.', 25549),
(116723, 'itIT', 'Percepisci la presenza di creature che un tempo sono state maledette e mutate in una nuova forma.', 'Percepisci la presenza di creature che un tempo sono state maledette e mutate in una nuova forma.', 25549),
(116722, 'itIT', 'Ci sono delle rovine nei paraggi, ma percepisci una forte sensazione di solitudine.', 'Ci sono delle rovine nei paraggi, ma percepisci una forte sensazione di solitudine.', 25549),
(116721, 'itIT', 'Intuisci che Timirgos è ipnotizzato da un qualche tipo di luce brillante.', 'Intuisci che Timirgos è ipnotizzato da un qualche tipo di luce brillante.', 25549),
(116720, 'itIT', 'Senti lo scrosciare delicato dell''acqua.', 'Senti lo scrosciare delicato dell''acqua.', 25549),
(116719, 'itIT', 'Ancora una volta, sono in pace.', '', 25549),
(116718, 'itIT', 'Muori, traditore Vilfedele!', '', 25549),
(116717, 'itIT', '', 'Venite, fratelli! La Legione Infuocata attacca!', 25549),
(116716, 'itIT', '', 'Perché? Non sei un demone!', 25549),
(116715, 'itIT', 'Di'' a Valeera che stiamo vegliando su di lei.', '', 25549),
(116714, 'itIT', 'Osi disturbare il mio riposo, demone?', '', 25549),
(116713, 'itIT', 'Vai dall''Arcidruido e spiegagli cos''è successo. Io esaminerò ciò che rimane di questa cosa.', '', 25549),
(116712, 'itIT', 'No... non va bene! Distruggi la pianta malefica prima che scappi!', '', 25549),
(116711, 'itIT', 'Hai con te un campione dell''Incubo?', 'Hai con te un campione dell''Incubo?', 25549),
(116710, 'itIT', 'Gli Shal''dorei sono... i prescelti...', 'Noi siamo... i prescelti...', 25549),
(116709, 'itIT', 'Anath''ashar!', 'Anath''ashar!', 25549),
(116708, 'itIT', 'Morte agli stranieri!', 'Nessuno può sfidarci!', 25549),
