UPDATE `broadcast_text_locale` SET `MaleText_lang`='Oreficeria? Un gran bel lavoro, davvero. Puoi comprare le tue forniture da Bero nel Bazar delle Stelle, nell''ala sinistra dell''edificio principale.$B$BTi segno la posizione sulla mappa.', `FemaleText_lang`='Oreficeria? Un gran bel lavoro, davvero. Puoi comprare le tue forniture da Bero nel Bazar delle Stelle, nell''ala sinistra dell''edificio principale.$B$BTi segno la posizione sulla mappa.', `VerifiedBuild`=25549 WHERE (`ID`=64879 AND `locale`='itIT');
