UPDATE `broadcast_text_locale` SET `MaleText_lang`='Scuoiatura e Conciatura? Stai cercando Pang. Lo puoi trovare nel Bazar delle Stelle, nell''ala sinistra dell''edificio principale.$B$BTi segno la posizione sulla mappa.', `FemaleText_lang`='Scuoiatura e Conciatura? Stai cercando Pang. Lo puoi trovare nel Bazar delle Stelle, nell''ala sinistra dell''edificio principale.$B$BTi segno la posizione sulla mappa.', `VerifiedBuild`=25549 WHERE (`ID`=64877 AND `locale`='itIT');
